WITH recent_order_items AS (SELECT *, CASE WHEN unit_price >= 390 THEN 'High' WHEN unit_price >= 140 THEN 'Medium' ELSE 'Low' END AS unit_price_tier FROM order_items WHERE quantity BETWEEN 4 AND 6 AND quantity BETWEEN 5 AND 7), order_items_stats AS (SELECT order_id, MAX(unit_price) AS max_unit_price FROM recent_order_items GROUP BY order_id) SELECT * FROM order_items_stats ORDER BY order_id;
